using Microsoft.CodeAnalysis;

namespace MagicCSharp.Generators.Declarations;

/// <summary>
///     Decides what a <c>[LogExecuting]</c> class gets: the decorator for its one use case interface, hand-written or
///     generated by <c>[GenerateInterface]</c> in the same compilation, or every reason it gets none.
/// </summary>
public static class ExecutingLogDecoratorPlanner
{
    public static ExecutingLogDecoratorResult Plan(ExecutingLogClassReading reading, ExecutingLogSettings settings, GeneratedInterfaceIndex generatedInterfaceIndex)
    {
        var useCaseClass = reading.UseCaseClass;
        var problems = ClassProblems(reading, settings);
        var decoratedInterfaces = UseCaseInterfaces(reading, settings, generatedInterfaceIndex);
        if (decoratedInterfaces.Count == 0)
        {
            problems.Add(Problem(ExecutingLogDiagnostics.NoUseCaseInterface, useCaseClass.Location, useCaseClass.Name, settings.MarkerInterfaceMetadataName));
        }
        else if (decoratedInterfaces.Count > 1)
        {
            var interfaceNames = string.Join(", ", decoratedInterfaces.Select(decoratedInterface => decoratedInterface.DisplayName));
            problems.Add(Problem(ExecutingLogDiagnostics.SeveralUseCaseInterfaces, useCaseClass.Location, useCaseClass.Name, interfaceNames));
        }
        else
        {
            problems.AddRange(MethodProblems(reading, decoratedInterfaces[0]));
        }

        if (problems.Count > 0)
        {
            return new ExecutingLogDecoratorResult
            {
                File = null,
                Diagnostics = new EquatableArray<DiagnosticInfo>(problems),
            };
        }

        return new ExecutingLogDecoratorResult
        {
            File = ExecutingLogDecoratorWriter.WriteFile(useCaseClass, decoratedInterfaces[0]),
            Diagnostics = EquatableArray<DiagnosticInfo>.Empty,
        };
    }

    private static List<DiagnosticInfo> ClassProblems(ExecutingLogClassReading reading, ExecutingLogSettings settings)
    {
        var useCaseClass = reading.UseCaseClass;
        var problems = new List<DiagnosticInfo>();
        if (useCaseClass.TypeParameters.Count > 0)
        {
            problems.Add(Problem(ExecutingLogDiagnostics.GenericClass, useCaseClass.Location, useCaseClass.Name));
        }

        if (useCaseClass.IsAbstract)
        {
            problems.Add(Problem(ExecutingLogDiagnostics.AbstractClass, useCaseClass.Location, useCaseClass.Name));
        }

        if (ReadOnlyUseCaseName.IsReadOnly(useCaseClass.Name, ReadOnlyUseCaseVerbs.All, settings.CallerPrefixes))
        {
            problems.Add(Problem(ExecutingLogDiagnostics.ReadOnlyUseCase, useCaseClass.Location, useCaseClass.Name));
        }

        if (reading.OwnExecutingLineLocation != null)
        {
            problems.Add(Problem(ExecutingLogDiagnostics.OwnExecutingLine, reading.OwnExecutingLineLocation, useCaseClass.Name));
        }

        return problems;
    }

    // An interface [GenerateInterface] writes for this class, plus every resolved interface extending the marker
    // that no other such interface already extends: IX : IBaseUseCase is one use case interface, not two.
    private static List<DecoratedInterface> UseCaseInterfaces(ExecutingLogClassReading reading, ExecutingLogSettings settings,
        GeneratedInterfaceIndex generatedInterfaceIndex)
    {
        var decoratedInterfaces = new List<DecoratedInterface>();
        var useCaseClass = reading.UseCaseClass;
        var namespacePrefix = useCaseClass.Namespace == "" ? "" : useCaseClass.Namespace + ".";
        if (generatedInterfaceIndex.TryFind(namespacePrefix + "I" + useCaseClass.Name, out var generatedInterface) &&
            generatedInterface.Class.FullyQualifiedName == useCaseClass.FullyQualifiedName)
        {
            decoratedInterfaces.Add(new DecoratedInterface
            {
                FullyQualifiedName = generatedInterface.InterfaceFullyQualifiedName,
                DisplayName = namespacePrefix + generatedInterface.InterfaceName,
                Methods = generatedInterface.Methods,
            });
        }

        var markerExtendingInterfaces = reading.ImplementedInterfaces
            .Where(implementedInterface => implementedInterface.ExtendedInterfaceMetadataNames.Contains(settings.MarkerInterfaceMetadataName))
            .ToArray();
        var extendedByAnother = new HashSet<string>(markerExtendingInterfaces.SelectMany(implementedInterface => implementedInterface.ExtendedInterfaceMetadataNames));
        foreach (var implementedInterfaceReading in markerExtendingInterfaces)
        {
            if (extendedByAnother.Contains(implementedInterfaceReading.DisplayName))
            {
                continue;
            }

            decoratedInterfaces.Add(new DecoratedInterface
            {
                FullyQualifiedName = implementedInterfaceReading.Interface.FullyQualifiedName,
                DisplayName = implementedInterfaceReading.DisplayName,
                Methods = implementedInterfaceReading.Methods,
            });
        }

        return decoratedInterfaces;
    }

    private static IEnumerable<DiagnosticInfo> MethodProblems(ExecutingLogClassReading reading, DecoratedInterface decoratedInterface)
    {
        var useCaseClassName = reading.UseCaseClass.Name;
        // Only Execute writes the line, so only its parameters can leak a secret or be read before they are assigned;
        // any other method is passed through as it is.
        var loggedMethods = decoratedInterface.Methods.Where(ExecutingLogDecoratorWriter.IsLogged).ToArray();
        var byReferenceProblems = loggedMethods.SelectMany(method => method.Parameters
            .Where(parameter => parameter.RefKind != RefKind.None)
            .Select(parameter => Problem(ExecutingLogDiagnostics.ByReferenceParameter, method.Location, parameter.Name, useCaseClassName)));
        var decoratedMethodLocations = loggedMethods.Select(method => method.Location).ToArray();
        var secretProblems = reading.SecretParameters
            .Where(secretParameter => decoratedMethodLocations.Contains(secretParameter.MethodLocation))
            .Select(secretParameter => Problem(ExecutingLogDiagnostics.SecretParameter, secretParameter.MethodLocation, secretParameter.ParameterName,
                useCaseClassName));
        return secretProblems.Concat(byReferenceProblems);
    }

    private static DiagnosticInfo Problem(DiagnosticDescriptor descriptor, SourceLocation? location, params string[] messageArguments)
    {
        return new DiagnosticInfo
        {
            Descriptor = descriptor,
            Location = location,
            MessageArguments = new EquatableArray<string>(messageArguments),
        };
    }
}
